    // While the workflow cannot run at all, earlier silence or failure rate problems stay open as they were,
    // instead of being reported as resolved.
    for (const type of ['stale', 'failure_rate']) {
      const key = `${r.workflowId}|${type}`;
      if ((previous.open || {})[key]) current[key] = previous.open[key];
    }
    continue;
  }
  if (r.maxSilenceMinutes !== null) {
    const since = r.lastSuccessAt ? Date.parse(r.lastSuccessAt) : firstSeen[r.workflowId];
    const silence = now - since;
    if (silence > r.maxSilenceMinutes * 60000) {
      open(r, 'stale', r.lastSuccessAt
        ? `*${name}* has not run successfully for ${durationText(silence)} (limit ${minutesText(r.maxSilenceMinutes)}). Last success: ${clockText(since, zone)}. ${runsLink}`
        : `*${name}* has had no successful run since the heartbeat started watching it ${durationText(silence)} ago (limit ${minutesText(r.maxSilenceMinutes)}). ${runsLink}`);
    }
  }
  if (r.minSuccessRate !== null && r.sampleRuns >= s.minRuns) {
    const rate = ((r.sampleRuns - r.sampleFailures) / r.sampleRuns) * 100;
    if (rate < r.minSuccessRate) {
      const latest = r.latestFailureId ? ` Latest failed run: ${s.editorUrl}/workflow/${encodeURIComponent(r.workflowId)}/executions/${r.latestFailureId}` : '';
      open(r, 'failure_rate', `*${name}* failed ${r.sampleFailures} of its last ${plural(r.sampleRuns, 'run')} (${fmt(rate)}% success, minimum ${fmt(r.minSuccessRate)}%).${latest}`, { rate });
    }
  }
}

const previousOpen = previous.open || {};
const newKeys = Object.keys(current).filter((k) => !previousOpen[k]);
// A problem of a workflow that is no longer watched is dropped, not reported as resolved.
const resolvedKeys = Object.keys(previousOpen).filter((k) => !current[k] && watchedIds.has(previousOpen[k].workflowId));
const resultById = Object.fromEntries(input.results.map((r) => [r.workflowId, r]));

function resolvedText(old) {
  const r = resultById[old.workflowId] || {};
  const name = slackEscape(old.label);
  if (old.type === 'not_found') return `*${name}* can be found in n8n again.`;
  if (old.type === 'archived') return `*${name}* is no longer archived.`;
  if (old.type === 'inactive') return `*${name}* is active again.`;
  if (old.type === 'stale') {
    if (r.maxSilenceMinutes === null || r.maxSilenceMinutes === undefined) return `*${name}* no longer has a silence limit.`;
    return r.lastSuccessAt ? `*${name}* ran successfully again (${clockText(Date.parse(r.lastSuccessAt), zone)}).` : `*${name}* is within its silence limit again.`;
  }
  if (r.minSuccessRate === null || r.minSuccessRate === undefined) return `*${name}* no longer has a success rate limit.`;
  if (r.sampleRuns >= s.minRuns) {
    const rate = ((r.sampleRuns - r.sampleFailures) / r.sampleRuns) * 100;
    return `*${name}* is back to ${fmt(rate)}% success over its last ${plural(r.sampleRuns, 'run')} (minimum ${fmt(r.minSuccessRate)}%).`;
  }
  return `*${name}* has fewer than ${s.minRuns} runs in the last ${durationText(s.rateHours * 3600000)}, so its failure rate is no longer judged.`;
}

const lines = [];
if (newKeys.length) {
  lines.push(`:rotating_light: *n8n heartbeat: ${plural(newKeys.length, 'new problem')}*`);
  newKeys.forEach((k) => lines.push(`• ${current[k].text}`));
}
if (resolvedKeys.length) {
  const stillOpen = Object.keys(current).length;
  lines.push(newKeys.length ? ':white_check_mark: *Resolved*' : `:white_check_mark: *n8n heartbeat: ${stillOpen ? plural(resolvedKeys.length, 'problem') + ' resolved' : 'all clear'}*`);
  resolvedKeys.forEach((k) => lines.push(`• ${resolvedText(previousOpen[k])}`));
}
const stillOpenOld = Object.keys(current).filter((k) => previousOpen[k]);
if (lines.length && stillOpenOld.length) {
  lines.push(`Still open: ${stillOpenOld.map((k) => `${slackEscape(current[k].label)} (${current[k].type.replace('_', ' ')})`).join(', ')}`);
}

const newOpen = {};
for (const [k, v] of Object.entries(current)) newOpen[k] = { ...v, since: previousOpen[k] ? previousOpen[k].since : now };
const summary = {
  checked: input.results.length,
  open: Object.values(newOpen).map((p) => ({ workflowId: p.workflowId, label: p.label, type: p.type })),
  new: newKeys.map((k) => ({ workflowId: current[k].workflowId, type: current[k].type })),
  resolved: resolvedKeys.map((k) => ({ workflowId: previousOpen[k].workflowId, type: previousOpen[k].type })),
};
return [{ json: { source: input.source, changed: lines.length > 0, text: lines.join('\n'), newState: { open: newOpen, firstSeen, lastRunAt: now }, summary } }];

// Slack refused the heartbeat message after its retries. The state is not saved, so the same
// problems count as new on the next run and are posted again.
const error = $input.first().json.error || {};
const detail = String(error.message || 'unknown error') + (error.description ? `: ${error.description}` : '');
const summary = $('Compare With Last Run').first().json.summary;
const changes = summary.new.map((p) => `${p.workflowId} ${p.type.replace('_', ' ')}`).concat(summary.resolved.map((p) => `${p.workflowId} ${p.type.replace('_', ' ')} resolved`));
return [{ json: { failure: `The heartbeat found ${changes.length} change(s) but could not post them to Slack (${detail.slice(0, 200)}). They will be posted on the next run: ${changes.join(', ')}.` } }];

// Saves which problems are open, so the next run only reports changes.
const compared = $('Compare With Last Run').first().json;
const store = $getWorkflowStaticData('global');
store.heartbeat = compared.newState;
return [{ json: { ok: true, source: compared.source, slackPosted: compared.changed, ...compared.summary } }];

// The check itself finished and its state is saved, but the uptime monitor did not get its ping.
// The run fails so the error workflow says why, instead of the monitor reporting a dead heartbeat with no reason.
const error = $input.first().json.error || {};
const detail = (String(error.message || 'unknown error') + (error.description ? `: ${error.description}` : '')).slice(0, 200);
return [{ json: { failure: `The heartbeat check finished and was saved, but the ping to HEARTBEAT_PING_URL failed after 2 tries (${detail}). Your uptime monitor will report the heartbeat as down until the ping works.` } }];
